package com.endiq.turtlelauncher.feature.logo

import android.content.ComponentName
import android.content.Context
import android.content.pm.PackageManager
import com.endiq.turtlelauncher.feature.LogoPackUnpacker
import com.endiq.turtlelauncher.feature.log.Logging

/**
 * Switches the launcher's home-screen icon to match the picked logo.
 *
 * Android does not allow an app to set its icon to an arbitrary image at runtime. Instead,
 * every bundled logo has its own `activity-alias` launcher entry and icon, generated by
 * tools/generate_home_icon_aliases.py. Exactly one entry is enabled at a time. Imported
 * logos (not in the bundled pack) have no entry, so they restore the default turtle icon.
 *
 * The alias name is derived from the file name (see [aliasFor]) so no lookup table is needed.
 */
object HomeScreenIcon {
    private const val TAG = "HomeScreenIcon"
    private const val CLASS_PREFIX = "com.endiq.turtlelauncher."
    private const val DEFAULT_ALIAS = "HomeIconDefault"
    private const val ALIAS_PREFIX = "HomeIcon_"
    private const val PREFS = "home_screen_icon"
    private const val KEY_ENABLED = "enabled_alias"

    /** True when [logoFileName] is a bundled logo that can be the home-screen icon. */
    fun isBundled(context: Context, logoFileName: String?): Boolean =
        logoFileName != null && logoFileName in LogoPackUnpacker.bundledNames(context)

    /** Alias class name for a bundled logo file, e.g. "0579-lavender-orbit-sparkles.png" -> "HomeIcon_0579_lavender_orbit_sparkles". */
    private fun aliasFor(logoFileName: String): String =
        ALIAS_PREFIX + logoFileName.removeSuffix(".png").replace('-', '_')

    /**
     * Makes the home-screen icon match [logoFileName] (null or an imported logo means the default).
     * Returns true when the switch succeeded.
     */
    fun apply(context: Context, logoFileName: String?): Boolean {
        val pm = context.packageManager
        val prefs = context.getSharedPreferences(PREFS, Context.MODE_PRIVATE)
        val previous = prefs.getString(KEY_ENABLED, DEFAULT_ALIAS) ?: DEFAULT_ALIAS
        val wanted = if (isBundled(context, logoFileName)) aliasFor(logoFileName!!) else DEFAULT_ALIAS
        if (wanted == previous) return true
        return try {
            // Enable the new entry before disabling the old one, so the app never has
            // zero launcher entries. If the entry is missing from the build, fall back to the default.
            val target = try {
                pm.setComponentEnabledSetting(
                    componentFor(context, wanted),
                    PackageManager.COMPONENT_ENABLED_STATE_ENABLED,
                    PackageManager.DONT_KILL_APP
                )
                wanted
            } catch (e: IllegalArgumentException) {
                Logging.w(TAG, "No home-screen entry for $wanted, using the default")
                DEFAULT_ALIAS
            }
            if (target != previous) {
                pm.setComponentEnabledSetting(
                    componentFor(context, previous),
                    PackageManager.COMPONENT_ENABLED_STATE_DISABLED,
                    PackageManager.DONT_KILL_APP
                )
            }
            prefs.edit().putString(KEY_ENABLED, target).apply()
            target == wanted
        } catch (e: Exception) {
            Logging.e(TAG, "Could not switch the home-screen icon", e)
            false
        }
    }

    private fun componentFor(context: Context, alias: String) =
        ComponentName(context.packageName, CLASS_PREFIX + alias)
}
